                new ExamQuestion { Number = 3, Category = "Relational Data Modeling", QuestionText = "What is the primary purpose of Entity Framework Core?", OptionA = "To create HTML pages automatically", OptionB = "To replace the MVC Controller", OptionC = "To map objects in code to relational database data", OptionD = "To replace the C# compiler", CorrectAnswer = "C", Explanation = "EF Core maps object models to relational tables." },
