                new ExamQuestion { Number = 5, Category = "Relational Data Modeling", QuestionText = "What does the following command primarily do? dotnet ef dbcontext scaffold \"ConnectionString\" Microsoft.EntityFrameworkCore.SqlServer -o Models", OptionA = "Deletes the database", OptionB = "Creates a new MVC project", OptionC = "Generates EF Core models and a DbContext from an existing database", OptionD = "Starts the MVC application", CorrectAnswer = "C", Explanation = "Scaffolding creates entity models from a live database connection string." },
                new ExamQuestion { Number = 6, Category = "Conceptual Data Architecture", QuestionText = "Where is a database connection string commonly stored in an ASP.NET Core MVC application?", OptionA = "Program.cs only", OptionB = "appsettings.json", OptionC = "Index.cshtml", OptionD = "Student.cs", CorrectAnswer = "B", Explanation = "appsettings.json is the standard configuration repository for connection settings." },
                new ExamQuestion { Number = 7, Category = "Conceptual Data Architecture", QuestionText = "A Student belongs to exactly one Section, while a Section can contain many students. What type of relationship is this?", OptionA = "One-to-One", OptionB = "One-to-Many", OptionC = "Many-to-Many", OptionD = "Many-to-One only", CorrectAnswer = "B", Explanation = "A single section has multiple student entities associated with it." },
                new ExamQuestion { Number = 8, Category = "Conceptual Data Architecture", QuestionText = "In the following example, what is SectionId? public int SectionId { get; set; } public Section Section { get; set; }", OptionA = "Primary key of Student", OptionB = "Foreign key referencing Section", OptionC = "Navigation property", OptionD = "Database connection string", CorrectAnswer = "B", Explanation = "SectionId functions as the foreign key referencing the parent table." },
                new ExamQuestion { Number = 9, Category = "Conceptual Data Architecture", QuestionText = "What is the purpose of a navigation property such as public Section Section { get; set; }?", OptionA = "It stores the database password", OptionB = "It represents a relationship to another entity", OptionC = "It creates a new database", OptionD = "It validates the student's name", CorrectAnswer = "B", Explanation = "Navigation properties enable traversal between related model entities." },
                new ExamQuestion { Number = 10, Category = "Conceptual Data Architecture", QuestionText = "What does .Include() generally allow EF Core to do?", OptionA = "Delete the Section table", OptionB = "Load related Section data together with Students", OptionC = "Create a new Student", OptionD = "Validate Student input", CorrectAnswer = "B", Explanation = "Include() performs eager loading of related entity records." },
