                new ExamQuestion { Number = 12, Category = "Data Normalization & Validation", QuestionText = "Consider this query: var students = _context.Students.Include(s => s.Section).ToList(); What is the main benefit of Include(s => s.Section)?", OptionA = "It loads the related Section navigation property", OptionB = "It creates a Section object manually", OptionC = "It removes the foreign key", OptionD = "It prevents the query from accessing the database", CorrectAnswer = "A", Explanation = "It ensures the related Section record is loaded alongside students." },
                new ExamQuestion { Number = 13, Category = "Data Normalization & Validation", QuestionText = "Which type of validation occurs in the browser before a request is sent to the server?", OptionA = "Database-level validation", OptionB = "Client-side validation", OptionC = "Server-side validation", OptionD = "EF Core migration validation", CorrectAnswer = "B", Explanation = "Client-side validation executes directly within the user browser." },
