                new ExamQuestion { Number = 16, Category = "SQL & CRUD Operations", QuestionText = "Which is the best reason for having a database-level unique constraint on StudentNumber?", OptionA = "It protects data integrity even if application-level validation is bypassed", OptionB = "It makes Razor Views render faster", OptionC = "It removes the need for a Controller", OptionD = "It automatically creates a ViewModel", CorrectAnswer = "A", Explanation = "Database constraints act as a final safety barrier for data integrity." },
                new ExamQuestion { Number = 17, Category = "SQL & CRUD Operations", QuestionText = "What is the purpose of a try...catch block in a controller?", OptionA = "It creates navigation properties", OptionB = "To catch and handle exceptions that may occur during execution", OptionC = "To generate database tables", OptionD = "To perform client-side validation", CorrectAnswer = "B", Explanation = "Try-catch blocks intercept and manage runtime application exceptions." },
                new ExamQuestion { Number = 18, Category = "SQL & CRUD Operations", QuestionText = "Which middleware is commonly used in ASP.NET Core for centralized exception handling?", OptionA = "UseDatabase()", OptionB = "UseExceptionHandler()", OptionC = "UseValidationHandler()", OptionD = "UseMvcDatabase()", CorrectAnswer = "B", Explanation = "UseExceptionHandler provides centralized global error handling middleware." },
